PARSERS = {
    'markdown': MarkdownParser,
    'python': PythonParser,
    'json': JSONParser,
    'yaml': JSONParser,  # YAML 也用 JSON 解析器（简化）
    'text': TextParser,
    'html': HTMLParser,
    'javascript': GenericCodeParser,
    'typescript': GenericCodeParser,
    'css': GenericCodeParser,
    'xml': HTMLParser,
    'csv': TextParser,
